package vn.crossdock;
import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import org.springframework.web.multipart.MultipartFile;import org.springframework.security.access.AccessDeniedException;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.transaction.annotation.Transactional;
import java.util.*;import java.security.Principal;import static vn.crossdock.Db.*;
@RestController @RequestMapping("/api") public class ApiController {
 final Db db;final QueryService query;final Workflow workflow;final MasterService master;final ExcelService excel;final PdfService pdf;final Settings settings;final PasswordEncoder encoder;
 public ApiController(Db d,QueryService q,Workflow w,MasterService m,ExcelService e,PdfService p,Settings s,PasswordEncoder enc){db=d;query=q;workflow=w;master=m;excel=e;pdf=p;settings=s;encoder=enc;}
 Map<String,Object> user(Principal p){return db.one("select * from nguoi_dung where code=? and active",p.getName());}
 void role(Map<String,Object>u,String r){if(!r.equals(s(u,"role")))throw new AccessDeniedException("Bạn không có quyền thực hiện thao tác này");}
 @GetMapping("/state")public Map<String,Object> state(Principal p){return query.state(p.getName());}
 @PostMapping("/action/{action}")public Map<String,Object> action(@PathVariable String action,@RequestBody Map<String,Object>p,Principal principal){var u=user(principal);role(u,Workflow.KHO.contains(action)?"KHO":"DP");require(Workflow.KHO.contains(action)||Workflow.DP.contains(action),"Thao tác không tồn tại");return Map.of("ok",true,"result",workflow.execute(action,p,n(u,"id")));}
 @PostMapping("/master/{table}")public Map<String,Object> master(@PathVariable String table,@RequestBody Map<String,Object>p,Principal principal){var u=user(principal);if(!MasterService.allowed(table,s(u,"role")))throw new AccessDeniedException("Danh mục không thuộc quyền của bạn");return Map.of("ok",true,"id",master.save(table,p,n(u,"id")));}
 @PostMapping("/excel")public Map<String,Object> excel(@RequestParam long lotId,@RequestParam(defaultValue="true")boolean preview,@RequestParam MultipartFile file,Principal principal)throws Exception{role(user(principal),"KHO");return excel.importBoxes(lotId,file,preview);}
 @GetMapping(value="/trip/{id}/pdf",produces=MediaType.APPLICATION_PDF_VALUE)public ResponseEntity<byte[]> pdf(@PathVariable long id,Principal p)throws Exception{var u=user(p);require(Set.of("DP","ADMIN").contains(s(u,"role")),"Không có quyền tải phiếu xuất");return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=phieu-xuat-"+id+".pdf").body(pdf.trip(id));}
 @GetMapping(value="/box/{id}/barcode",produces=MediaType.IMAGE_PNG_VALUE)public byte[] barcode(@PathVariable long id)throws Exception{String code=s(db.get("thung_hang",id),"code");var matrix=new com.google.zxing.MultiFormatWriter().encode(code,com.google.zxing.BarcodeFormat.CODE_128,440,100);var out=new java.io.ByteArrayOutputStream();com.google.zxing.client.j2se.MatrixToImageWriter.writeToStream(matrix,"PNG",out);return out.toByteArray();}
 @PostMapping("/settings")public Map<String,Object> settings(@RequestBody Map<String,Object>p,Principal principal)throws Exception{role(user(principal),"ADMIN");settings.save(p);return Map.of("ok",true);}
 @PostMapping("/account")@Transactional public Map<String,Object> account(@RequestBody Map<String,Object>p,Principal principal){var u=user(principal);require(!s(p,"name").isBlank()&&s(p,"email").contains("@"),"Tên/email chưa hợp lệ");if(!s(p,"newPassword").isBlank()){require(encoder.matches(s(p,"oldPassword"),s(u,"password")),"Mật khẩu hiện tại không đúng");require(s(p,"newPassword").length()>=8,"Mật khẩu mới ít nhất 8 ký tự");db.run("update nguoi_dung set password=? where id=?",encoder.encode(s(p,"newPassword")),n(u,"id"));}db.run("update nguoi_dung set name=?,email=? where id=?",s(p,"name"),s(p,"email"),n(u,"id"));return Map.of("ok",true);}
}
